SELECT COUNT(1)
FROM data_specialist


        (username LIKE #{like}
        OR specialist_name LIKE #{like}
        OR remark LIKE #{like})

SELECT id, username, specialist_name AS name, remark, enabled, create_time AS createTime, update_time AS updateTime FROM data_specialist
(username LIKE #{like} OR specialist_name LIKE #{like} OR remark LIKE #{like})
ORDER BY create_time DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT tenant_id
FROM data_specialist_tenant
WHERE specialist_id = #{specialistId}

SELECT COUNT(1)
FROM data_specialist_tenant
WHERE specialist_id = #{specialistId}
  AND tenant_id = #{tenantId}
LIMIT 1

SELECT COUNT(1)
FROM data_specialist
WHERE username = #{username}

    AND id != #{excludeId}
